        </div>
      </div>
      <div class="film" data-media>
        <div class="film-visual" aria-hidden="true">
          <img src="assets/poster.svg" alt="" width="960" height="540" fetchpriority="high">
          <video src="assets/scene.webm" poster="assets/poster.svg" muted playsinline preload="metadata" aria-hidden="true" hidden></video>
        </div>
        <button class="media-toggle" type="button" data-pause aria-label="Play background video" hidden>
          <svg data-play viewBox="0 0 16 16" aria-hidden="true"><path fill="currentColor" d="M4 2 14 8 4 14Z"/></svg>
          <svg data-stop viewBox="0 0 16 16" aria-hidden="true" hidden><path fill="currentColor" d="M3 2h4v12H3zm6 0h4v12H9z"/></svg>
        </button>
      </div>
    </section>
    <section id="work">
      <h2 data-reveal>Selected work</h2>
      <div class="work-entry">
        <p class="work-title" data-reveal data-delay="80">Tidal study / 2026</p>
        <button id="details" type="button">Show details</button>
        <p id="detail" hidden>Filmed on the northern coast.</p>
      </div>
    </section>
  </main>
  <script>window.analytics=[];document.querySelector('"'[data-track]').addEventListener('click',()=>window.analytics.push('explore'));document.querySelector('#details').addEventListener('click',()=>{document.querySelector('#detail').hidden="'!document.querySelector('"'#detail').hidden});</script>
  <script>
    // Enhancements leave the document visible when APIs or initialization fail.
    (() => {
      if ("'!window.matchMedia) return;
      const reduce = matchMedia('"'(prefers-reduced-motion: reduce)');
      const controller = new AbortController();
      const options = { signal: controller.signal };
      const animations = new Set();
      let revealObserver, mediaObserver, dead = false;
      const cancelMotion = () => {
        revealObserver?.disconnect();
        animations.forEach(animation => animation.cancel());
        animations.clear();
      };
      const enter = element => {
        if (dead || reduce.matches || "'!element.animate ||
            element.matches('"'a,button,input,select,textarea,[tabindex]') ||
            element.querySelector('a,button,input,select,textarea,[tabindex]')) return;
        const animation = element.animate([
          { opacity: .75, transform: 'translateY(14px)' },
          { opacity: 1, transform: 'none' }
        ], { duration: 600, delay: Math.min(160, Math.max(0, Number(element.dataset.delay) || 0)), easing: 'cubic-bezier(.22,1,.36,1)' });
        animations.add(animation);
        animation.finished.then(() => animations.delete(animation), () => animations.delete(animation));
      };
      try {
        if ("'!reduce.matches) {
          document.querySelectorAll('"'[data-enter]').forEach(enter);
          const pending = new Set(document.querySelectorAll('[data-reveal]'));
          if (pending.size && 'IntersectionObserver' in window) {
            revealObserver = new IntersectionObserver(entries => {
              entries.forEach(entry => {
                if ("'!entry.isIntersecting) return;
                revealObserver.unobserve(entry.target);
                pending.delete(entry.target);
                enter(entry.target);
              });
              if (!pending.size) revealObserver.disconnect();
            }, { threshold: 0 });
            pending.forEach(element => revealObserver.observe(element));
          }
        }
        reduce.addEventListener('"'change', cancelMotion, options);
      } catch { cancelMotion(); }

      const root = document.querySelector('[data-media]');
      const video = root.querySelector('video');
      const button = root.querySelector('[data-pause]');
      let visible = false, userPaused = false, blocked = false, epoch = 0;
      const setPlaying = playing => {
        button.setAttribute('aria-label', playing ? 'Pause background video' : 'Play background video');
        button.querySelector('[data-play]').hidden = playing;
        button.querySelector('[data-stop]').hidden = "'!playing;
      };
      const still = () => {
        epoch++;
        video.pause();
        video.hidden = true;
        setPlaying(false);
      };
      const sync = async () => {
        button.hidden = reduce.matches || !('"'IntersectionObserver' in window);
        if (dead || "'!visible || userPaused || blocked || reduce.matches || document.hidden) {
          still();
          return;
        }
        const attempt = ++epoch;
        try {
          await video.play();
          if (attempt !== epoch) return;
          video.hidden = false;
          setPlaying(true);
        } catch {
          if (attempt !== epoch) return;
          blocked = true;
          still();
        }
      };
      try {
        video.muted = true;
        video.playsInline = true;
        video.loop = true;
        button.addEventListener('"'click', () => {
          userPaused = "'!video.paused;
          blocked = false;
          sync();
        }, options);
        video.addEventListener('"'error', () => { blocked = true; still(); }, options);
        reduce.addEventListener('change', sync, options);
        document.addEventListener('visibilitychange', sync, options);
        if ('IntersectionObserver' in window) {
          mediaObserver = new IntersectionObserver(([entry]) => {
            visible = entry.isIntersecting && entry.intersectionRatio > 0;
            sync();
          }, { threshold: [0, .001] });
          mediaObserver.observe(root);
        }
      } catch { still(); button.hidden = true; }
      const cleanup = () => {
        dead = true;
        cancelMotion();
        mediaObserver?.disconnect();
        still();
        controller.abort();
      };
      // A bfcache return remounts enhancements without replaying the original analytics script.
      window.addEventListener('pagehide', cleanup, { once: true });
      window.addEventListener('pageshow', event => {
        if (event.persisted) {
          dead = false;
          // The static poster remains usable after lifecycle teardown.
          button.hidden = true;
        }
      }, { once: true });
    })();
  </script>
</body>
</html>
